import type { ContentBlockManifestEntry } from './contentBlocks.js'
import type { ProposalContentEnrichment } from '../salesContent/types.js'
import { coerceEnrichmentBlocks } from '../salesContent/enrichmentBlocks.js'

// Hand-authored, NOT generated by scripts/scanVariables.mjs — same reasoning as
// coverFields.ts/page02Fields.ts. Two distinct gaps the scanner can't see here:
//
// 1. Text split across sibling DOM nodes for styling (the heading's white
//    prefix + orange "[Client First Name]" span) — neither half was
//    previously tagged, so the bracket token never actually got resolved by
//    patchPreviewDom even though it was already tracked in the bracket
//    PLACEHOLDER_REGISTRY (manifest.generated.ts). Tagging both halves fixes
//    that silently-dead placeholder.
// 2. The three "Prepared for: [Client Name]" / "Business: [Business Name]" /
//    "Website: [Website Link]" value spans — generated via `.map()` over a JS
//    array literal, so their JSX children are expressions, not literal text,
//    invisible to the scanner. Same silently-dead-placeholder bug as (1).
//
// The demand keyword chips are NOT listed here — they're a variable-length
// repeatable array (add/remove/reorder/duplicate), generated dynamically in
// ProposalEditor.tsx from the current keywords array length, not a fixed
// manifest. DEFAULT_PAGE07_KEYWORDS is exported so ProposalEditor.tsx has a
// single source of truth for the template's own default, matching
// ProposalPage07.tsx's own DEFAULT_KEYWORDS exactly.

export const DEFAULT_PAGE07_KEYWORDS = [
  'Security company Bristol',
  'Event security Bristol',
  'Static guarding Bristol',
  'Security company Bath',
  'Security company Weston-super-Mare',
  'Security company South Gloucestershire',
  'Security company North Somerset',
]

/** Parses Page 07's keyword array out of its single JSON-stringified contentOverride — the one place this variable-length repeatable collection is stored, still inside the existing generic override map (no new storage). Shared by all three render call sites (Editor, Review, ClientProposalView) so they can never drift into parsing this differently — was previously duplicated only inside ProposalEditor.tsx, which is why Review/ClientProposalView never actually rendered real keywords before this. */
export function parsePage07Keywords(raw: string | undefined): string[] {
  if (!raw) return DEFAULT_PAGE07_KEYWORDS
  try {
    const parsed = JSON.parse(raw)
    return Array.isArray(parsed) && parsed.every((v) => typeof v === 'string') ? parsed : DEFAULT_PAGE07_KEYWORDS
  } catch {
    return DEFAULT_PAGE07_KEYWORDS
  }
}

export const DEFAULT_PAGE07_ENRICHMENT: ProposalContentEnrichment = { blocks: [] }

/**
 * Backfills a stored `page07.enrichment` blob to the full
 * `ProposalContentEnrichment` shape — same reasoning as
 * `normalizePricingCards`: `JSON.parse` (via `parseCollection`/direct
 * `JSON.parse` in the render paths) has no shape validation, so a proposal
 * saved before this field existed (or a partially-malformed stored value)
 * comes back with fields genuinely `undefined` at runtime. Delegates to the
 * same coerceEnrichmentBlocks used by the API-side generation path (see
 * modules/salesContent/enrichmentBlocks.ts) rather than a separate
 * re-hydration implementation, so a stored block is now validated as
 * strictly as a freshly-generated one — a block that never had enough real
 * data now correctly disappears here too, instead of rendering as a near-
 * empty box.
 */
export function normalizeEnrichment(raw: Partial<ProposalContentEnrichment> | null | undefined): ProposalContentEnrichment {
  if (!raw || typeof raw !== 'object' || !Array.isArray(raw.blocks)) return DEFAULT_PAGE07_ENRICHMENT
  return { blocks: coerceEnrichmentBlocks(raw.blocks, 2) }
}

/** Parses the `page07.enrichment` contentOverride (a single JSON object, not a `parseCollection` array) and backfills it to a safe, complete shape — the one parse path all three render call sites (Editor, Review, ClientProposalView) should share so they can never drift into parsing this differently. */
export function parseEnrichmentOverride(raw: string | undefined): ProposalContentEnrichment {
  if (!raw) return DEFAULT_PAGE07_ENRICHMENT
  try {
    return normalizeEnrichment(JSON.parse(raw))
  } catch {
    return DEFAULT_PAGE07_ENRICHMENT
  }
}

export function getPage07FieldEntries(): ContentBlockManifestEntry[] {
  return [
    { key: 'page07.heading', page: 'page07', originalText: 'Your Custom Proposal,', label: 'Main Heading', variants: ['both'] },
    {
      key: 'page07.clientFirstNameHeading',
      page: 'page07',
      originalText: '[Client First Name]',
      label: 'Heading — Client First Name',
      variants: ['both'],
    },
    {
      key: 'page07.description',
      page: 'page07',
      originalText: 'Built around your pipeline, not a template. Here is exactly where revenue is leaking and how we close it.',
      label: 'Sub Heading',
      variants: ['both'],
    },
    { key: 'page07.clientNameValue', page: 'page07', originalText: '[Client Name]', label: 'Prepared For (value)', variants: ['both'] },
    { key: 'page07.businessNameValue', page: 'page07', originalText: '[Business Name]', label: 'Business (value)', variants: ['both'] },
    { key: 'page07.websiteLinkValue', page: 'page07', originalText: '[Website Link]', label: 'Website (value)', variants: ['both'] },
    { key: 'page07.funnelStep0', page: 'page07', originalText: 'Increase visibility', label: 'Funnel Step 1', variants: ['both'] },
    { key: 'page07.funnelStep1', page: 'page07', originalText: 'Increase enquiries', label: 'Funnel Step 2', variants: ['both'] },
    { key: 'page07.funnelStep2', page: 'page07', originalText: 'Increase contracts.', label: 'Funnel Step 3', variants: ['both'] },
  ]
}
